import {escapeHTML as esc,fa} from './model.js';

const KEY='hplgame-prototype-v1',TTL=30*86400000;
let state=load(),warning='',modal='',returnFocus;
const titles=['هدف بازی','کنترل بازیکن','قانون برد'];
function load(){
 try{const s=JSON.parse(localStorage.getItem(KEY)||'null');if(!s||!Number.isFinite(s.updatedAt)||s.updatedAt>Date.now()+60000||Date.now()-s.updatedAt>TTL){localStorage.removeItem(KEY);return {user:null,game:null};}
 const user=s.user&&typeof s.user.name==='string'?{name:s.user.name.slice(0,40)}:null;
 const g=s.game;return {user,game:g&&typeof g.id==='string'&&typeof g.idea==='string'?{id:g.id,idea:g.idea.slice(0,600),step:Math.max(0,Math.min(3,Math.floor(Number(g.step))||0)),won:g.won===true,messages:Array.isArray(g.messages)?g.messages.filter(m=>m&&['user','coach'].includes(m.role)&&typeof m.text==='string').slice(-30).map(m=>({role:m.role,text:m.text.slice(0,500)})):[]}:null};
 }catch{return {user:null,game:null};}
}
function save(){try{localStorage.setItem(KEY,JSON.stringify({...state,updatedAt:Date.now()}));warning='';}catch{warning='ذخیرهٔ محلی در دسترس نیست؛ این جلسه تا بازخوانی صفحه در حافظه می‌ماند.';}}
function idea(){try{return JSON.parse(localStorage.getItem('hplgame-discovery-v1')||'{}').idea||'';}catch{return '';}}
function auth(signup){return `<section class="panel proto-auth"><span class="badge">پروتوتایپ هفتهٔ ۳</span><h1>${signup?'ساخت پروفایل آزمایشی':'ورود به تجربهٔ آزمایشی'}</h1><p>اینجا حساب واقعی ساخته نمی‌شود. فقط یک نام مستعار وارد کن؛ رمز عبور و ایمیل نمی‌خواهیم.</p><form id="proto-auth" novalidate><label for="proto-name">نام مستعار بازی‌ساز</label><input id="proto-name" name="name" maxlength="40" autocomplete="off" required placeholder="مثلاً بازی‌ساز کوچک" aria-describedby="proto-auth-error"><p id="proto-auth-error" role="status"></p><button class="btn primary" type="submit">${signup?'ساخت پروفایل و ادامه':'ورود آزمایشی و ادامه'} ←</button></form><a href="#/studio/${signup?'login':'signup'}">${signup?'قبلاً پروفایل آزمایشی ساخته‌ای؟ ورود':'اولین بارته؟ ثبت‌نام آزمایشی'}</a><a href="#/login">ورود به حساب واقعی</a><a href="#/">بازگشت به ایده</a></section>`;}
function nav(view){return `<nav class="proto-tabs" aria-label="مراحل پروتوتایپ">${[['coach','۱ · مربی و درس'],['preview','۲ · بوم بازی'],['games','۳ · بازی‌های من']].map(([id,t])=>`<a class="btn ${view===id?'primary':'secondary'}" href="#/studio/${id}" ${view===id?'aria-current="page"':''}>${t}</a>`).join('')}</nav>`;}
function lesson(){const n=state.game.step;return n===3?{text:'سه قدم طراحی را تمام کردی؛ حالا نمونهٔ آماده را بازی و آزمایش کن.',question:'',answers:[],correct:0}:[
 {text:'نسخهٔ اول باید یک هدف کوچک داشته باشد. در نمونهٔ ما، بازیکن سه ستاره را پیدا می‌کند.',question:'هدف روشن نسخهٔ اول کدام است؟',answers:['جمع کردن سه ستاره','ساخت صد دنیا'],correct:0},
 {text:'بازیکن با کلیدهای جهت یا دکمه‌های لمسی حرکت می‌کند. هر حرکت یک خانه است.',question:'کنترل قابل فهم کدام است؟',answers:['دکمه‌های بدون راهنما','جهت‌ها با برچسب روشن'],correct:1},
 {text:'وقتی هر سه ستاره جمع شد، پیام برد نشان می‌دهیم. اجرای بازی به‌تنهایی برد نیست.',question:'چه زمانی برد ثبت می‌شود؟',answers:['همین که اجرا را بزنیم','بعد از جمع شدن هر سه ستاره'],correct:1}
 ][n];}
function coach(){const g=state.game,l=lesson();return `<div class="proto-columns"><section class="panel"><span class="badge">درس کوتاه · حدود ۲ دقیقه</span><h2>${g.step===3?'آمادهٔ آزمایش!':titles[g.step]}</h2><progress max="3" value="${g.step}" aria-label="پیشرفت درس‌های پروتوتایپ"></progress><p>${fa(g.step)} از ۳ قدم</p><p>${l.text}</p>${g.step<3?`<form id="proto-lesson"><fieldset><legend>${l.question}</legend>${l.answers.map((a,i)=>`<label class="quiz-choice"><input type="radio" name="answer" value="${i}" required> ${a}</label>`).join('')}</fieldset><p id="proto-feedback" role="status"></p><button class="btn primary">بررسی پاسخ و ادامه</button></form>`:'<a class="btn primary" href="#/studio/preview">اجرای نمونهٔ بازی ←</a>'}</section><section class="panel coach-chat"><div class="chat-heading"><span class="avatar" aria-label="هوپی">ه</span><div><h2>هوپی، مربی تو</h2><small>نمونهٔ رابط مربی هوش مصنوعی · پاسخ‌های آماده و آفلاین</small></div></div><div class="chat-messages" role="log" aria-label="چت مربی پروتوتایپ" aria-live="polite">${[{role:'coach',text:'سلام بازی‌ساز! ایده‌ات را داریم. با یک هدف کوچک شروع کنیم؛ من در هر قدم راهنمایی‌ات می‌کنم.'},...g.messages].map(m=>`<p class="chat-message ${m.role}"><b>${m.role==='coach'?'هوپی':'تو'}</b>${esc(m.text)}</p>`).join('')}</div><button class="btn secondary" data-proto="hint">برای این قدم مثال بزن</button><form id="proto-chat"><label for="proto-message">پیام به هوپی</label><div class="proto-chat-row"><input id="proto-message" maxlength="500" required placeholder="از این قدم بپرس…"><button class="btn primary">ارسال</button></div></form></section></div>`;}
function preview(){return `<section class="panel"><div class="section-head"><div><h2>آزمایشگاه ستاره‌ها</h2><p>یک نمونهٔ ثابت برای آزمودن جریان محصول؛ از ایدهٔ دلخواه تولید نشده است.</p></div><button class="btn secondary" data-proto="restart">شروع دوباره</button></div><canvas id="proto-canvas" width="480" height="320" tabindex="0" role="img" aria-label="بوم بازی جمع‌آوری سه ستاره؛ با جهت‌ها حرکت کن"></canvas><p id="proto-game-status" role="status" aria-live="polite">برای شروع، اجرای بازی را بزن.</p><div class="proto-controls"><button class="btn primary" data-proto="run">اجرای بازی</button><button class="btn secondary" data-move="up" aria-label="حرکت بالا">↑</button><button class="btn secondary" data-move="right" aria-label="حرکت راست">→</button><button class="btn secondary" data-move="down" aria-label="حرکت پایین">↓</button><button class="btn secondary" data-move="left" aria-label="حرکت چپ">←</button></div><p>هر کلیک یا کلید جهت یک خانه حرکت می‌کند. ستاره‌های بالا راست، پایین راست و پایین چپ را بگیر.</p><a href="#/studio/coach">بازگشت به مربی</a></section>`;}
function games(){return `<section class="panel"><div class="section-head"><h2>بازی اول تو</h2><button class="btn primary" data-proto="new">ساخت بازی دوم 🔒</button></div><p>${esc(state.game.idea)}</p><span class="badge">رایگان · ${state.game.won?'نمونه با موفقیت بازی شد':'در حال یادگیری'}</span><p>بازی اول همیشه در دسترس است. از بازی دوم به بعد، مدل محصول نیازمند اشتراک است.</p><a class="btn secondary" href="#/studio/preview">ادامهٔ بازی اول</a><button class="btn secondary" data-proto="export">دانلود دادهٔ این نمونه</button><button class="btn ghost" data-proto="delete">پاک کردن دادهٔ پروتوتایپ</button></section>`;}
export function prototypePage(route){const view=route.split('/')[1]||'coach';if(!state.user||['login','signup'].includes(view))return auth(view==='signup');if(!state.game)return `<section class="panel empty"><h1>ایده‌ات را همراه بیاور</h1><p>از ورودی صفحهٔ اصلی شروع کن، سپس اینجا برگرد.</p><a class="btn primary" href="#/">نوشتن ایده</a><button class="btn secondary" data-proto="continue">دریافت ایده و ادامه</button></section>`;return `<section class="proto-heading"><div><span class="badge">پروتوتایپ تعاملی · هفتهٔ ۳</span><h1>${esc(state.user.name)}، بازی‌ات را قدم‌به‌قدم بساز.</h1><p>${esc(state.game.idea)}</p></div><button class="btn secondary" data-proto="logout">خروج آزمایشی</button></section>${nav(view)}${view==='preview'?preview():view==='games'?games():coach()}<p role="status">${esc(warning)}</p><div id="proto-modal-root"></div>`;}
function openModal(kind){modal=kind;returnFocus=document.activeElement;const root=document.querySelector('#proto-modal-root');if(!root)return;
 root.innerHTML=`<div class="proto-backdrop"><section class="panel proto-dialog" role="dialog" aria-modal="true" aria-labelledby="proto-modal-title"><button class="btn ghost" data-close aria-label="بستن پنجره">×</button><h2 id="proto-modal-title">${kind==='delete'?'پاک کردن دادهٔ نمونه؟':'بازی بعدی، یک قدم جلوتر'}</h2>${kind==='delete'?'<p>فقط پروفایل، بازی و پیام‌های این پروتوتایپ حذف می‌شوند. ایده و پژوهش هفته‌های قبل باقی می‌مانند.</p><button class="btn primary" id="proto-confirm-delete">بله، دادهٔ نمونه پاک شود</button>':'<p>بازی اول رایگان است؛ ساخت بازی دوم به بعد به اشتراک نیاز دارد.</p><ul><li>ادامهٔ بازی اول رایگان</li><li>بازی‌های بیشتر با اشتراک در نسخهٔ آینده</li></ul><p class="badge">پروتوتایپ · خرید و پرداخت هنوز فعال نیست</p><button class="btn primary" id="proto-plan">مشاهدهٔ وضعیت اشتراک</button><p id="proto-plan-status" role="status"></p>'}<button class="btn secondary" data-close>${kind==='delete'?'انصراف':'ادامهٔ بازی رایگان'}</button></section></div>`;
 // Only sibling page sections are made inert; the dialog stays interactive.
 const main=document.querySelector('#main-content');for(const child of main?.children||[])if(child!==root)child.inert=true;
 const outside=[document.querySelector('.sidebar'),document.querySelector('.topbar'),document.querySelector('.mobile-nav'),document.querySelector('.hopi-launch')];outside.forEach(x=>{if(x)x.inert=true;});
 function close(){root.innerHTML='';modal='';for(const child of main?.children||[])child.inert=false;outside.forEach(x=>{if(x)x.inert=false;});returnFocus?.focus();}
 root.querySelectorAll('[data-close]').forEach(b=>b.onclick=close);root.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();close();}if(e.key==='Tab'){const nodes=[...root.querySelectorAll('button')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}};
 root.querySelector('#proto-plan')?.addEventListener('click',()=>{root.querySelector('#proto-plan-status').textContent='اشتراک و درگاه هنوز راه‌اندازی نشده‌اند؛ هیچ پرداختی انجام نمی‌شود. بازی اول را ادامه بده.';});
 root.querySelector('#proto-confirm-delete')?.addEventListener('click',()=>{try{localStorage.removeItem(KEY);}catch{}state={user:null,game:null};close();location.hash='#/studio/login';});root.querySelector('button').focus();
}
export function bindPrototype({navigate,render,toast}){
 function start(){const text=idea();if(typeof text!=='string'||text.trim().length<2){navigate('');toast('اول ایدهٔ بازی‌ات را بنویس.');return;}if(!state.game){state.game={id:crypto.randomUUID(),idea:text.slice(0,600),step:0,won:false,messages:[]};save();}navigate('studio/coach');}
 document.querySelector('#proto-auth')?.addEventListener('submit',e=>{e.preventDefault();const name=new FormData(e.currentTarget).get('name').trim();if(name.length<2||name.length>40){document.querySelector('#proto-auth-error').textContent='یک نام مستعار ۲ تا ۴۰ نویسه‌ای بنویس.';return;}state.user={name};save();start();});
 function chat(text){state.game.messages.push({role:'user',text:text.slice(0,500)},{role:'coach',text:`برای ایدهٔ «${state.game.idea.slice(0,80)}»: ${lesson().text} ${state.game.step===3?'در بوم با جهت‌ها سه ستاره را بگیر.':'پاسخ تمرین همین قدم را انتخاب کن؛ اشتباه کردن فرصت یادگیری است.'}`});state.game.messages=state.game.messages.slice(-30);save();render();document.querySelector('#proto-message')?.focus();}
 document.querySelector('#proto-chat')?.addEventListener('submit',e=>{e.preventDefault();const text=document.querySelector('#proto-message').value.trim();if(text)chat(text);});
 document.querySelector('#proto-lesson')?.addEventListener('submit',e=>{e.preventDefault();const value=new FormData(e.currentTarget).get('answer');if(value===null||Number(value)!==lesson().correct){document.querySelector('#proto-feedback').textContent='دوباره امتحان کن؛ راهنمای هوپی بالای سؤال است.';return;}state.game.step++;save();render();toast('آفرین! قدم بعد باز شد.');});
 document.querySelectorAll('[data-proto]').forEach(b=>b.addEventListener('click',()=>{switch(b.dataset.proto){case'continue':start();break;case'hint':chat('برای این قدم مثال بزن');break;case'new':openModal('paywall');break;case'delete':openModal('delete');break;case'logout':state.user=null;save();navigate('studio/login');break;case'export':{const a=document.createElement('a'),url=URL.createObjectURL(new Blob([JSON.stringify({scope:'local-prototype',game:state.game},null,2)],{type:'application/json'}));a.href=url;a.download='hplgame-prototype.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}}}));
 const canvas=document.querySelector('#proto-canvas');if(canvas)bindBoard(canvas);
}
function bindBoard(canvas){const ctx=canvas.getContext('2d');let running=false,x=0,y=0,stars=new Set(['5,0','5,3','0,3']);
 const status=document.querySelector('#proto-game-status');function draw(){if(!ctx)return;ctx.fillStyle='#24151f';ctx.fillRect(0,0,480,320);for(let r=0;r<4;r++)for(let c=0;c<6;c++){ctx.strokeStyle='#754052';ctx.strokeRect(c*80+1,r*80+1,78,78);}ctx.font='36px sans-serif';ctx.textAlign='center';for(const pos of stars){const [c,r]=pos.split(',').map(Number);ctx.fillStyle='#ffd58a';ctx.fillText('★',c*80+40,r*80+53);}ctx.fillStyle='#be3144';ctx.beginPath();ctx.arc(x*80+40,y*80+40,24,0,Math.PI*2);ctx.fill();ctx.fillStyle='white';ctx.fillText('●',x*80+40,y*80+52);}
 function reset(){running=false;x=0;y=0;stars=new Set(['5,0','5,3','0,3']);status.textContent='برای شروع، اجرای بازی را بزن.';draw();}
 function move(dir){if(!running){status.textContent='اول اجرای بازی را بزن.';return;}x=Math.max(0,Math.min(5,x+(dir==='right'?1:dir==='left'?-1:0)));y=Math.max(0,Math.min(3,y+(dir==='down'?1:dir==='up'?-1:0)));stars.delete(`${x},${y}`);status.textContent=`${fa(3-stars.size)} از ۳ ستاره · خانهٔ ${fa(x+1)}، ${fa(y+1)}`;if(!stars.size){running=false;state.game.won=true;save();status.textContent='آفرین! هر سه ستاره را گرفتی و برنده شدی. می‌توانی دوباره بازی کنی.';}draw();}
 document.querySelector('[data-proto=run]').onclick=()=>{running=true;status.textContent='بازی شروع شد؛ با جهت‌ها سه ستاره را جمع کن.';canvas.focus();};document.querySelector('[data-proto=restart]').onclick=reset;document.querySelectorAll('[data-move]').forEach(b=>b.onclick=()=>move(b.dataset.move));canvas.onkeydown=e=>{const dir={ArrowLeft:'left',ArrowRight:'right',ArrowUp:'up',ArrowDown:'down'}[e.key];if(dir){e.preventDefault();move(dir);}};draw();
}
